#!/usr/bin/env bash
# Regenerates the TypeScript bindings from schema/docktopus.fbs.
# Requires flatc 25.12.19 on PATH, the same compiler the C++ package uses.
# Rust messages are generated by Cargo. This script does not use Nix.

set -euo pipefail

expected="25.12.19"
root="$(cd "$(dirname "$0")/.." && pwd)"
schema="$root/schema/docktopus.fbs"

if ! command -v flatc >/dev/null 2>&1; then
  echo "flatc ${expected} is required on PATH." >&2
  exit 1
fi

actual="$(flatc --version | awk '{print $NF}')"
if [[ "$actual" != "$expected" ]]; then
  echo "flatc ${expected} is required, found ${actual}." >&2
  exit 1
fi

flatc --ts --gen-all --gen-mutable --gen-name-strings --require-explicit-ids \
  -o "$root/typescript/src" "$schema"
